public class Compiler_init_TriageGen0Test {

    private Compiler compiler;
    private CompilerOptions options;
    private ErrorManager errorManager;

    @Mock
    private JSModule mockModule;

    @Mock
    private JSModule mockDependentModule;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        errorManager = new ErrorManager();
        compiler = new Compiler(errorManager);
        options = new CompilerOptions();
    }

    @Test
    public void testInit_Success() {
        // Arrange
        JSSourceFile extern = JSSourceFile.fromCode("extern.js", "");
        JSModule module = mock(JSModule.class);
        when(module.getSource()).thenReturn("function test() {}");
        when(module.getName()).thenReturn("module.js");

        JSSourceFile[] externs = new JSSourceFile[]{extern};
        JSModule[] modules = new JSModule[]{module};

        // Act
        compiler.init(externs, modules, options);

        // Assert
        assertEquals(0, compiler.getErrorCount());
        assertEquals(0, compiler.getWarningCount());
        assertNotNull(compiler.getInput("module.js"));
    }

    @Test
    public void testInit_WithNoExternsAndNoModules() {
        // Arrange
        JSSourceFile[] externs = new JSSourceFile[0];
        JSModule[] modules = new JSModule[0];

        // Act
        compiler.init(externs, modules, options);

        // Assert
        assertEquals(0, compiler.getErrorCount());
    }

