    @Test(expected = Exception.class)
    public void testInit_NullModules_ThrowsException() {
        // This tests the checkFirstModule(modules) call which likely throws NullPointerException
        compiler.init(new JSSourceFile[0], null, options);
    }

    @Test
    public void testInit_SingleModule() {
        // Arrange
        JSModule module = mock(JSModule.class);
        when(module.getSource()).thenReturn("var x = 1;");
        when(module.getName()).thenReturn("test.js");

        // Act
        compiler.init(new JSSourceFile[0], new JSModule[]{module}, options);

        // Assert
        assertEquals(0, compiler.getErrorCount());
    }

    @Test
    public void testInit_MultipleModules() {
        // Arrange
        JSModule m1 = mock(JSModule.class);
        when(m1.getSource()).thenReturn("var a = 1;");
        when(m1.getName()).thenReturn("m1.js");

        JSModule m2 = mock(JSModule.class);
        when(m2.getSource()).thenReturn("var b = 2;");
        when(m2.getName()).thenReturn("m2.js");

        // Act
        compiler.init(new JSSourceFile[0], new JSModule[]{m1, m2}, options);

        // Assert
        assertEquals(0, compiler.getErrorCount());
    }
